/**
 * SevaSaathi AI - Stage 7: Explainable Priority Engine
 *
 * Calculates a strictly deterministic, explainable priority score for civic incidents.
 *
 * Fixed Formula Weights (Total = 100):
 * - Severity: 25%
 * - Safety Risk: 20%
 * - People Affected: 20%
 * - Recurrence: 15%
 * - Location Sensitivity: 10%
 * - Time Unresolved: 10%
 *
 * Priority Thresholds:
 * - 90–100 -> "Critical"
 * - 75–89  -> "High"
 * - 50–74  -> "Medium"
 * - 0–49   -> "Low"
 *
 * Note: Numerical score is strictly computed by deterministic backend logic,
 * NEVER hallucinated or generated by an LLM.
 */

const { doc, getDoc, getDocs, collection, query, where, updateDoc } = require('firebase/firestore');
const { db } = require('../config/firebase');

const WEIGHTS = {
  severity: 25,
  safetyRisk: 20,
  peopleAffected: 20,
  recurrence: 15,
  locationSensitivity: 10,
  timeUnresolved: 10,
};

const DISCLAIMER_TEXT =
  'System-calculated priority for municipal decision support. Not an official government decision.';

/**
 * Extracts milliseconds timestamp from various Firestore or JS formats.
 */
function parseTimestampMillis(ts) {
  if (!ts) return null;
  if (typeof ts.toMillis === 'function') return ts.toMillis();
  if (typeof ts.seconds === 'number') return ts.seconds * 1000;
  if (typeof ts === 'string' || typeof ts === 'number') {
    const parsed = new Date(ts).getTime();
    if (!isNaN(parsed)) return parsed;
  }
  return null;
}

/**
 * Evaluates the 6 deterministic factors from report and incident data.
 *
 * @param {Object} report - Target report document data
 * @param {Array<Object>} [relatedReports=[]] - Related reports from Incident Fusion
 * @returns {Object} { factors, evidence, score, level }
 */
function evaluatePriorityFactors(report = {}, relatedReports = []) {
  const evidence = [];

  const textToSearch = `${report.description || ''} ${report.locationStatus || ''} ${report.category || ''}`.toLowerCase();

  // -------------------------------------------------------------
  // 1. Severity (25%)
  // -------------------------------------------------------------
  let severityScore = 50;
  let severitySource = 'AI report analysis';
  const aiSeverity = (report.aiAnalysis?.severity || '').trim().toLowerCase();

  if (aiSeverity === 'critical') {
    severityScore = 95;
    evidence.push('Critical severity flagged by triage analysis');
  } else if (aiSeverity === 'high') {
    severityScore = 80;
    evidence.push('High severity issue requiring expedited municipal response');
  } else if (aiSeverity === 'medium') {
    severityScore = 55;
    evidence.push('Moderate severity civic grievance');
  } else if (aiSeverity === 'low') {
    severityScore = 30;
    evidence.push('Low operational severity issue');
  } else {
    // Fallback baseline if AI analysis is not yet available
    severityScore = 50;
    severitySource = 'default baseline (AI analysis unavailable)';
    evidence.push('Baseline severity applied (AI triage pending)');
  }

  // -------------------------------------------------------------
  // 2. Safety Risk (20%)
  // -------------------------------------------------------------
  let safetyScore = 50;
  let safetySource = 'AI report analysis';
  const aiRisk = (report.aiAnalysis?.safetyRisk || '').trim().toLowerCase();

  if (aiRisk === 'high') {
    safetyScore = 90;
    evidence.push('High safety risk posing physical danger to citizens');
  } else if (aiRisk === 'medium') {
    safetyScore = 60;
    evidence.push('Moderate safety concern for local pedestrians and vehicles');
  } else if (aiRisk === 'low') {
    safetyScore = 30;
    evidence.push('Minimal physical safety risk');
  } else {
    safetyScore = 50;
    safetySource = 'default baseline (AI analysis unavailable)';
    evidence.push('Baseline safety risk applied');
  }

  // -------------------------------------------------------------
  // 3. People Affected (20%)
  // -------------------------------------------------------------
  let peopleScore = 40;
  const peopleSource = 'incident data';
  const relCount = report.incidentFusion?.relatedReportIds?.length || relatedReports.length || 0;

  // Multiple reports in the area imply high citizen exposure
  if (relCount >= 3) {
    peopleScore = 80;
    evidence.push(`Broad community impact with ${relCount} related citizen reports`);
  } else if (relCount >= 1) {
    peopleScore = 70;
    evidence.push(`Multiple citizen reports indicate widespread area disturbance`);
  } else {
    peopleScore = 40;
    evidence.push('Single localized citizen report');
  }

  // Check for public assembly or high-footfall area keywords
  const publicAreaKeywords = [
    'school',
    'hospital',
    'market',
    'main road',
    'bus stand',
    'railway',
    'junction',
    'traffic',
    'residents',
    'children',
    'street',
  ];
  const matchedKeywords = publicAreaKeywords.filter((kw) => textToSearch.includes(kw));
  if (matchedKeywords.length > 0) {
    peopleScore = Math.min(100, peopleScore + 15);
    evidence.push(`High public footfall indicator: ${matchedKeywords.slice(0, 2).join(', ')}`);
  }

  // -------------------------------------------------------------
  // 4. Recurrence (15%)
  // -------------------------------------------------------------
  let recurrenceScore = 30;
  let recurrenceSource = 'related reports';
  const fusionStatus = report.incidentFusion?.fusionStatus;

  if (fusionStatus === 'High confidence related') {
    recurrenceScore = 90;
    evidence.push('High recurrence: confirmed persistent incident with overlapping reports');
  } else if (fusionStatus === 'Officer review') {
    recurrenceScore = 75;
    evidence.push('Probable recurrence: overlapping nearby reports detected');
  } else if (report.incidentFusion) {
    recurrenceScore = 30;
    evidence.push('No concurrent reports detected (isolated occurrence)');
  } else {
    recurrenceScore = 40;
    recurrenceSource = 'default (fusion data unavailable)';
    evidence.push('Recurrence baseline applied (fusion check pending)');
  }

  // Keyword check for chronic issues
  if (
    textToSearch.includes('again') ||
    textToSearch.includes('repeatedly') ||
    textToSearch.includes('every time') ||
    textToSearch.includes('recurring')
  ) {
    recurrenceScore = Math.min(100, recurrenceScore + 10);
    evidence.push('Report notes chronic recurring issue');
  }

  // -------------------------------------------------------------
  // 5. Location Sensitivity (10%)
  // -------------------------------------------------------------
  let locationScore = 50;
  const locationSource = 'location data';

  if (
    textToSearch.includes('school') ||
    textToSearch.includes('college') ||
    textToSearch.includes('kindergarten')
  ) {
    locationScore = 100;
    evidence.push('Critical sensitive zone: school / educational institution nearby');
  } else if (
    textToSearch.includes('hospital') ||
    textToSearch.includes('clinic') ||
    textToSearch.includes('healthcare')
  ) {
    locationScore = 100;
    evidence.push('Critical sensitive zone: hospital / medical facility nearby');
  } else if (
    textToSearch.includes('market') ||
    textToSearch.includes('bus stop') ||
    textToSearch.includes('railway') ||
    textToSearch.includes('junction')
  ) {
    locationScore = 85;
    evidence.push('High-density civic area: commercial market / transit hub');
  } else if (textToSearch.includes('road') || textToSearch.includes('street')) {
    locationScore = 70;
    evidence.push('Active public thoroughfare');
  } else {
    locationScore = 50;
    evidence.push('Standard neighborhood civic zone');
  }

  // -------------------------------------------------------------
  // 6. Time Unresolved (10%)
  // -------------------------------------------------------------
  let timeScore = 40;
  let timeSource = 'timestamps';
  const createdMillis = parseTimestampMillis(report.createdAt);

  if (createdMillis) {
    const hoursElapsed = Math.max(0, (Date.now() - createdMillis) / (1000 * 60 * 60));
    if (hoursElapsed >= 72) {
      timeScore = 95;
      evidence.push(`Longstanding unresolved incident (> ${Math.round(hoursElapsed)}h elapsed)`);
    } else if (hoursElapsed >= 24) {
      timeScore = 75;
      evidence.push(`Unresolved for over a day (~${Math.round(hoursElapsed)}h elapsed)`);
    } else if (hoursElapsed >= 6) {
      timeScore = 60;
      evidence.push(`Unresolved for ${Math.round(hoursElapsed)} hours`);
    } else if (hoursElapsed >= 1) {
      timeScore = 50;
      evidence.push(`Active for ${Math.round(hoursElapsed)} hour(s)`);
    } else {
      timeScore = 40;
      evidence.push('Recently submitted incident (< 1h ago)');
    }
  } else {
    timeScore = 50;
    timeSource = 'default (timestamp unavailable)';
    evidence.push('Standard active queue timeframe');
  }

  // -------------------------------------------------------------
  // Compute Weighted Contributions and Final Deterministic Score
  // -------------------------------------------------------------
  const factorMap = {
    severity: { score: severityScore, weight: WEIGHTS.severity, source: severitySource },
    safetyRisk: { score: safetyScore, weight: WEIGHTS.safetyRisk, source: safetySource },
    peopleAffected: { score: peopleScore, weight: WEIGHTS.peopleAffected, source: peopleSource },
    recurrence: { score: recurrenceScore, weight: WEIGHTS.recurrence, source: recurrenceSource },
    locationSensitivity: {
      score: locationScore,
      weight: WEIGHTS.locationSensitivity,
      source: locationSource,
    },
    timeUnresolved: { score: timeScore, weight: WEIGHTS.timeUnresolved, source: timeSource },
  };

  const factors = {};
  let totalScoreRaw = 0;

  for (const [key, f] of Object.entries(factorMap)) {
    const contribution = Math.round(((f.score * f.weight) / 100) * 100) / 100;
    factors[key] = {
      score: f.score,
      weight: f.weight,
      contribution: contribution,
      source: f.source,
    };
    totalScoreRaw += contribution;
  }

  // Final rounded score clamped strictly between 0 and 100
  const finalScore = Math.max(0, Math.min(100, Math.round(totalScoreRaw)));

  // Priority Level thresholds
  let level = 'Low';
  if (finalScore >= 90) {
    level = 'Critical';
  } else if (finalScore >= 75) {
    level = 'High';
  } else if (finalScore >= 50) {
    level = 'Medium';
  } else {
    level = 'Low';
  }

  return {
    score: finalScore,
    level,
    factors,
    evidence,
    formulaVersion: 'v1',
    disclaimer: DISCLAIMER_TEXT,
    calculatedAt: new Date().toISOString(),
  };
}

/**
 * Loads a target report from Firestore and calculates its deterministic priority.
 *
 * @param {string} identifier - Firestore docId or human reportId
 * @returns {Promise<{ docId: string, reportId: string, priorityAssessment: Object }>}
 */
async function calculateAndSavePriority(identifier) {
  if (!identifier) {
    throw new Error('Report identifier is required to calculate priority');
  }

  let targetDocId = null;
  let targetReport = null;

  // 1. Check direct doc ID
  try {
    const docRef = doc(db, 'reports', identifier);
    const snap = await getDoc(docRef);
    if (snap.exists()) {
      targetDocId = snap.id;
      targetReport = snap.data();
    }
  } catch (_) {
    // Continue
  }

  // 2. Check by human reportId if not resolved
  if (!targetReport) {
    const q = query(collection(db, 'reports'), where('reportId', '==', identifier));
    const snap = await getDocs(q);
    if (!snap.empty) {
      targetDocId = snap.docs[0].id;
      targetReport = snap.docs[0].data();
    }
  }

  if (!targetReport) {
    throw new Error(`Report not found in Firestore for identifier: ${identifier}`);
  }

  // 3. Load related reports if present
  const relatedReports = [];
  const relatedIds = targetReport.incidentFusion?.relatedReportIds || [];
  for (const relId of relatedIds) {
    try {
      const q = query(collection(db, 'reports'), where('reportId', '==', relId));
      const snap = await getDocs(q);
      if (!snap.empty) {
        snap.forEach((d) => {
          if (d.id !== targetDocId) relatedReports.push(d.data());
        });
      }
    } catch (_) {}
  }

  // 4. Calculate deterministic priority
  const priorityAssessment = evaluatePriorityFactors(targetReport, relatedReports);

  // 5. Update Firestore document under `priorityAssessment` without overwriting other fields
  const reportRef = doc(db, 'reports', targetDocId);
  await updateDoc(reportRef, {
    priorityAssessment,
  });

  console.log(
    `[Priority Engine] Report ${targetReport.reportId || targetDocId}: Score=${priorityAssessment.score}, Level=${priorityAssessment.level}`
  );

  return {
    docId: targetDocId,
    reportId: targetReport.reportId || targetDocId,
    priorityAssessment,
  };
}

module.exports = {
  evaluatePriorityFactors,
  calculateAndSavePriority,
  WEIGHTS,
  DISCLAIMER_TEXT,
};
